    assert_eq!(error_code(&set(&mut s, "q", json!({"Fifo": false}))), "UnsupportedOperation");
    assert_eq!(error_code(&set(&mut s, "q", json!({"Fifo": true, "ContentBasedDeduplication": true}))), "UnsupportedOperation");
