    for name in ["b", "a_", "a-", "a.fifo", "A", "a1", "ab", "a"] {
        let attributes = if name.ends_with(".fifo") { fifo_attributes() } else { json!({}) };
        s.create(name, attributes);
    }
    let list = |s: &mut Session, command: Value| s.ok(command)["QueueNames"].clone();
    assert_eq!(
        list(&mut s, json!({"Command": "ListQueues"})),
        json!(["A", "a", "a-", "a.fifo", "a1", "a_", "ab", "b"])
    );
    assert_eq!(
        list(&mut s, json!({"Command": "ListQueues", "Prefix": "a"})),
        json!(["a", "a-", "a.fifo", "a1", "a_", "ab"])
    );
    assert_eq!(list(&mut s, json!({"Command": "ListQueues", "Prefix": "a."})), json!(["a.fifo"]));
    assert_eq!(list(&mut s, json!({"Command": "ListQueues", "Prefix": "zz"})), json!([]));
    assert_eq!(list(&mut s, json!({"Command": "ListQueues", "Prefix": ""})).as_array().map(Vec::len), Some(8));
