    let mut s = Session::default();
    s.create("q", json!({}));
    s.send("q", "a");
    s.send("q", "b");
    s.ok(json!({"Command": "ReceiveMessage", "QueueName": "q", "VisibilityTimeout": 5}));
    assert_eq!(s.receive_bodies("q", 1), ["b"]);
    s.tick(5);
    assert_eq!(s.receive_bodies("q", 2), ["a"], "b is still in flight");
