fn send_message_rules_apply_in_spec_order() {
    let mut s = Session::default();
    s.create("std", json!({}));
    s.create("f.fifo", fifo_attributes());
    let send = |s: &mut Session, queue: &str, extra: Value| {
        let mut command = json!({"Command": "SendMessage", "QueueName": queue, "Body": "b"});
        command.as_object_mut().expect("object").extend(extra.as_object().expect("object").clone());
        s.run(command)
    };
    assert_eq!(error_code(&send(&mut s, "std", json!({"GroupId": "g"}))), "UnsupportedOperation");
    assert_eq!(error_code(&send(&mut s, "std", json!({"DeduplicationId": "d"}))), "UnsupportedOperation");
    assert_eq!(error_code(&send(&mut s, "f.fifo", json!({"DelaySeconds": 0}))), "UnsupportedOperation");
    assert_eq!(error_code(&send(&mut s, "f.fifo", json!({"DeduplicationId": "d"}))), "MissingParameter");
    assert_eq!(error_code(&send(&mut s, "f.fifo", json!({"GroupId": "g"}))), "MissingParameter");
    assert_eq!(error_code(&send(&mut s, "f.fifo", json!({"GroupId": "g!", "DeduplicationId": "d"}))), "InvalidParameterValue");
    assert_eq!(error_code(&send(&mut s, "std", json!({"DelaySeconds": 901}))), "InvalidParameterValue");
    assert_eq!(error_code(&s.run(json!({"Command": "SendMessage", "QueueName": "std", "Body": ""}))), "InvalidParameterValue");
    let long = "\u{e9}".repeat(513);
    assert_eq!(error_code(&s.run(json!({"Command": "SendMessage", "QueueName": "std", "Body": long}))), "InvalidParameterValue");
    let fits = "\u{e9}".repeat(512);
    s.send("std", &fits);
    assert_eq!(s.send("std", "x"), json!({"ok": true, "MessageId": "m-2"}), "failed sends use no id");
}

