#[test]
fn message_moves_to_the_dead_letter_queue_after_max_receive_count_deliveries() {
    let mut s = Session::default();
    dead_letter_setup(&mut s, json!({}));
    s.send("q", "poison");
    s.send("q", "fine");
    for _ in 0..2 {
        assert_eq!(s.receive_bodies("q", 1), ["poison"]);
        s.tick(1);
        s.ok(json!({"Command": "DeleteMessage", "QueueName": "q", "ReceiptHandle": "r-2"}));
        break;
    }
    // Third receive: "poison" has been delivered once and deleted above, so redo cleanly.
    let mut s = Session::default();
    dead_letter_setup(&mut s, json!({}));
    s.send("q", "poison");
    s.send("q", "fine");
    s.receive("q", 1);
    s.tick(1);
    s.receive("q", 1);
    s.tick(1);
    let delivered = s.receive("q", 10);
    assert_eq!(delivered.len(), 1);
    assert_eq!(delivered[0]["Body"], "fine");
    assert_eq!(s.counts("q"), json!({"Visible": 0, "InFlight": 1, "Delayed": 0}));

    let moved = s.receive("dead", 1);
    assert_eq!(moved, [
        json!({"MessageId": "m-1", "ReceiptHandle": "r-5", "Body": "poison", "ReceiveCount": 1, "SentAt": 0, "FirstReceivedAt": 2}),
    ]);
}

